<template>
  <view class="wrap">
    <!-- 筛选区域 -->
    <view class="filter-box">
      <!-- 日期筛选 -->
      <view class="filter-item" @tap="openDatePicker">
        <text class="label">预约日期</text>
        <text class="val">{{ selectDate || '全部日期' }}</text>
        <uni-icons type="arrowdown" size="20"></uni-icons>
      </view>

      <!-- 服务类型筛选 -->
      <view class="filter-item" @tap="showTypePopup = true">
        <text class="label">服务类型</text>
        <text class="val">{{ selectTypeName || '全部类型' }}</text>
        <uni-icons type="arrowdown" size="20"></uni-icons>
      </view>
    </view>

    <!-- 预约列表 -->
    <view class="list-box">
      <view class="record-item" v-for="item in recordList" :key="item.id">
        <view class="item-top">
          <text class="type-tag">{{ item.serviceType }}</text>
          <text class="date">{{ item.createTime }}</text>
        </view>
        <view class="item-content">
          <view class="row">
            <text class="name">项目：{{ item.serviceName }}</text>
          </view>
          <view class="row">
            <text class="time">预约时段：{{ item.appointTime }}</text>
          </view>
          <view class="row">
            <text class="price">¥{{ item.price }}</text>
            <text class="status" :class="statusClass(item.status)">{{ item.statusText }}</text>
          </view>
        </view>
      </view>

      <!-- 空数据 -->
      <view class="empty" v-if="recordList.length === 0">
        <image src="/static/empty.png" class="empty-img"></image>
        <text class="empty-txt">暂无预约记录</text>
      </view>
    </view>

    <!-- 服务类型弹窗 -->
    <uni-popup v-model="showTypePopup" position="bottom">
      <view class="popup-content">
        <view class="popup-title">选择服务类型</view>
        <view class="type-list">
          <view 
            class="type-item" 
            :class="{active: selectType === ''}"
            @tap="chooseType('', '全部类型')"
          >全部</view>
          <view 
            class="type-item" 
            :class="{active: selectType === '美甲'}"
            @tap="chooseType('美甲', '美甲')"
          >美甲</view>
          <view 
            class="type-item" 
            :class="{active: selectType === '纹眉'}"
            @tap="chooseType('纹眉', '纹眉')"
          >纹眉</view>
          <view 
            class="type-item" 
            :class="{active: selectType === '美睫'}"
            @tap="chooseType('美睫', '美睫')"
          >美睫</view>
          <view 
            class="type-item" 
            :class="{active: selectType === '脱毛'}"
            @tap="chooseType('脱毛', '脱毛')"
          >脱毛</view>
        </view>
        <view class="cancel-btn" @tap="showTypePopup = false">取消</view>
      </view>
    </uni-popup>
  </view>
</template>

<script>
export default {
  data() {
    return {
      // 筛选条件
      selectDate: '',        // 选中日期
      selectType: '',        // 选中服务类型
      selectTypeName: '',    // 类型显示文本
      showTypePopup: false,  // 类型弹窗显隐

      // 服务类型列表
      typeOptions: ['美甲', '纹眉', '美睫', '脱毛'],

      // 预约记录假数据
      recordList: [
        {
          id: 1,
          serviceType: '美甲',
          serviceName: '纯色美甲+跳色',
          createTime: '2026-06-08',
          appointTime: '2026-06-10 14:00',
          price: 98,
          status: 1,
          statusText: '已完成'
        },
        {
          id: 2,
          serviceType: '美睫',
          serviceName: '自然款睫毛嫁接',
          createTime: '2026-06-09',
          appointTime: '2026-06-11 10:30',
          price: 168,
          status: 0,
          statusText: '待到店'
        },
        {
          id: 3,
          serviceType: '脱毛',
          serviceName: '腋下单次脱毛',
          createTime: '2026-06-07',
          appointTime: '2026-06-09 16:00',
          price: 68,
          status: 2,
          statusText: '已取消'
        }
      ]
    }
  },
  onShow() {
    // 页面显示可重新请求接口刷新数据
    this.getRecordList()
  },
  methods: {
    // 打开日期选择器
    openDatePicker() {
      uni.showDatePicker({
        title: '选择预约日期',
        success: (res) => {
          this.selectDate = res.value
          this.getRecordList() // 选完日期重新查询
        }
      })
    },

    // 选择服务类型
    chooseType(type, name) {
      this.selectType = type
      this.selectTypeName = name
      this.showTypePopup = false
      this.getRecordList() // 选完类型重新查询
    },

    // 根据状态设置样式
    statusClass(status) {
      switch(status) {
        case 0: return 'wait'
        case 1: return 'finish'
        case 2: return 'cancel'
        default: return ''
      }
    },

    // 核心：根据条件筛选/请求数据
    getRecordList() {
      // 实际项目替换为接口请求，传参：selectDate、selectType
      /*
      uni.request({
        url: '你的后端接口地址',
        data: {
          date: this.selectDate,
          serviceType: this.selectType
        },
        success: res => {
          this.recordList = res.data
        }
      })
      */

      // 本地前端筛选（演示用）
      let list = [...this.recordList]
      // 日期筛选
      if (this.selectDate) {
        list = list.filter(item => item.createTime === this.selectDate)
      }
      // 类型筛选
      if (this.selectType) {
        list = list.filter(item => item.serviceType === this.selectType)
      }
      this.recordList = list
    }
  }
}
</script>

